uired type="text" placeholder="ok" class="field-input font-mono" /></label><label v-if="!isHTTPType" class="field-wrap"><span class="field-label">Target host</span><input v-model.trim="form.targetHost" required type="text" placeholder="example.com" class="field-input font-mono" /></label><label v-if="form.monitorType === 'tcp'" class="field-wrap"><span class="field-label">TCP port</span><input v-model.number="form.targetPort" required min="1" max="65535" type="number" class="field-input font-mono" /></label><label v-if="form.monitorType === 'dns'" class="field-wrap"><span class="field-label">DNS record</span><select v-model="form.dnsRecordType" class="field-input"><option value="A">A</option><option value="AAAA">AAAA</option><option value="CNAME">CNAME</option></select></label><label class="field-wrap"><span class="field-label">Interval seconds</span><input v-model.number="form.intervalSeconds" required min="15" max="86400" type="number" class="field-input font-mono" /></label><label class="field-wrap"><span class="field-label">Timeout seconds</span><input v-model.number="form.timeoutSeconds" required min="1" max="120" type="number" class="field-input font-mono" /></label><label class="field-wrap"><span class="field-label">Retries</span><input v-model.number="form.retryCount" required min="0" max="5" type="number" class="field-input font-mono" /></label></div><div class="form-options"><label class="toggle-row"><input v-model="form.enabled" type="checkbox" /><span><strong>Start monitoring</strong><small>When disabled, status becomes Paused.</small></span></label><label class="toggle-row"><input v-model="form.notifyOnFailure" type="checkbox" /><span><strong>Notify on status change</strong><small>Send when an incident opens or recovers.</small></span></label></div><p v-if="formError" class="form-error">{{ formError }}</p><div class="form-actions"><button type="button" class="secondary-button" @click="closeForm">Cancel</button><button type="submit" class="primary-button" :disabled="isSaving">{{ isSaving ? 'Saving...' : editingId ? 'Save changes' : 'Create monitor' }}</button></div></form></Modal>
    <Modal :is-open="isGroupFormOpen" :title="editingGroupId ? 'Edit group' : 'Add group'" max-width="max-w-md" @close="closeGroupForm"><form class="form-stack" @submit.prevent="saveGroup"><label class="field-wrap"><span class="field-label">Group name</span><input v-model.trim="groupForm.name" required maxlength="120" class="field-input" /></label><label class="field-wrap"><span class="field-label">Description</span><textarea v-model.trim="groupForm.description" rows="3" class="field-input" /></label><label class="toggle-row"><input v-model="groupForm.enabled" type="checkbox" /><span><strong>Enabled</strong><small>Enabled groups can be selected when creating a monitor.</small></span></label><p v-if="groupFormError" class="form-error">{{ groupFormError }}</p><div class="form-actions"><button type="button" class="secondary-button" @click="closeGroupForm">Cancel</button><button type="submit" class="primary-button" :disabled="isSavingGroup">{{ isSavingGroup ? 'Saving...' : 'Save group' }}</button></div></form></Modal>
    <Modal :is-open="Boolean(confirmAction)" :title="confirmTitle" max-width="max-w-md" @close="closeConfirm"><div v-if="confirmAction" class="confirm-content"><p class="text-sm text-text-main">{{ confirmAction.kind === 'archive' ? `Archive “${confirmTargetName}”?` : confirmAction.kind === 'restore' ? `Restore “${confirmTargetName}”?` : confirmAction.kind === 'purge' ? `Remove configuration for “${confirmTargetName}”?` : `Delete group “${confirmTargetName}”?` }}</p><p class="mt-2 text-xs leading-5 text-text-secondary">{{ confirmAction.kind === 'archive' ? 'Monitoring will stop. Check history, incidents, timelines, and notification logs will remain available for audit.' : confirmAction.kind === 'restore' ? 'The monitor will be restored as PAUSED with its previous history. Resume it after verifying the configuration.' : confirmAction.kind === 'purge' ? 'The configuration will disappear from active and archived lists. Checks, incidents, timelines, notification logs, and reports remain available for audit. Registering it again creates a new monitor identity.' : 'Monitors in this group will remain available and move to Ungrouped.' }}</p><label v-if="confirmAction.kind === 'archive'" class="field-wrap mt-4"><span class="field-label">Reason</span><textarea v-model.trim="archiveReason" rows="3" maxlength="500" class="field-input" placeholder="Optional audit reason" /></label><label v-if="confirmAction.kind === 'purge'" class="field-wrap mt-4"><span class="field-label">Type monitor name to confirm</span><input v-model.trim="purgeConfirmation" class="field-input" :placeholder="confirmTargetName" autocomplete="off" /></label><p v-if="confirmError" class="form-error">{{ confirmError }}</p><div class="form-actions"><button type="button" class="secondary-button" @click="closeConfirm">Cancel</button><button type="button" class="primary-button" :disabled="isConfirming || (confirmAction.kind === 'purge' && purgeConfirmation.trim().toLowerCase() !== confirmTargetName.trim().toLowerCase())" @click="confirmLifecycleAction">{{ isConfirming ? 'Processing...' : confirmAction.kind === 'archive' ? 'Archive monitor' : confirmAction.kind === 'restore' ? 'Restore monitor' : confirmAction.kind === 'purge' ? 'Remove configuration' : 'Delete group' }}</button></div></div></Modal>
    <aside v-if="isChecksDrawerOpen" class="drawer-backdrop" @click.self="isChecksDrawerOpen = false"><section class="checks-drawer" aria-label="Check history"><div class="drawer-header"><div><p class="eyebrow">Raw check history</p><h2 class="drawer-title">{{ store.selectedMonitor?.monitor.name }}</h2><p class="panel-note">Last 90 days · 10 items per page</p></div><button type="button" class="icon-button" aria-label="Close check history" @click="isChecksDrawerOpen = false"><X class="h-4 w-4" /></button></div><div v-if="store.checksLoading" class="empty-state">Loading check history...</div><div v-else-if="!store.checks.length" class="empty-state">No raw checks recorded yet.</div><div v-else class="drawer-check-list"><div v-for="check in store.checks" :key="check.id" class="drawer-check-row"><div class="flex min-w-0 items-start gap-3"><span class="status-dot" :class="statusDot(check.status)" /><div class="min-w-0"><strong class="block text-xs text-text-main">{{ check.status }}</strong><span class="drawer-check-time">{{ formatDateTime(check.checkedAt) }}</span><span class="drawer-check-error">{{ checkSummary(check) }}</span></div></div><span class="font-mono text-[10px] text-text-muted">{{ check.latencyMs || 0 }}ms</span></div></div><div class="drawer-footer"><span class="text-[10px] font-mono text-text-muted">{{ store.checksTotal }} total checks</span><div class="drawer-pagination"><button type="button" class="compact-button" :disabled="historyPage <= 1 || store.checksLoading" @click="changeHistoryPage(historyPage - 1)">Previous</button><span class="text-[10px] font-mono text-text-secondary">{{ historyPage }} / {{ store.checksTotalPages }}</span><button type="button" class="compact-button" :disabled="historyPage >= store.checksTotalPages || store.checksLoading" @click="changeHistoryPage(historyPage + 1)">Next</button></div></div></section></aside>
