<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useAuthStore } from '../stores/authStore';
import { usePublicMonitoringStore } from '../stores/publicMonitoringStore';
import { useLiveStore } from '../stores/liveStore';
import StatCard from '../components/common/StatCard.vue';
import Skeleton from '../components/common/Skeleton.vue';
import Modal from '../components/common/Modal.vue';
import PublicMonitoringChart from '../components/publicMonitoring/PublicMonitoringChart.vue';
import { publicMonitorTypeLabel } from '../utils/publicMonitorLabels';
import type { PublicMonitor, PublicMonitorGroup, PublicMonitorType } from '../types';
import { Activity, Archive, CheckCircle, CircleAlert, CircleCheck, ChevronRight, FolderKanban, Globe2, PauseCircle, Pencil, Plus, RefreshCw, Search, Trash2, Server, X } from 'lucide-vue-next';

const route = useRoute(); const router = useRouter(); const authStore = useAuthStore(); const store = usePublicMonitoringStore(); const liveStore = useLiveStore();
const tabs = [{ value: 'monitors', label: 'Monitors', icon: Server }, { value: 'groups', label: 'Groups', icon: FolderKanban }, { value: 'archived', label: 'Archived', icon: Archive }] as const;
type TabValue = (typeof tabs)[number]['value']; const activeTab = ref<TabValue>(route.query.tab === 'groups' ? 'groups' : route.query.tab === 'archived' ? 'archived' : 'monitors');
const canCreate = computed(() => authStore.hasPermission('public_monitoring.create')); const canEdit = computed(() => authStore.hasPermission('public_monitoring.edit')); const canDelete = computed(() => authStore.hasPermission('public_monitoring.delete')); const canCreateGroups = computed(() => authStore.hasPermission('public_monitoring.groups.create')); const canEditGroups = computed(() => authStore.hasPermission('public_monitoring.groups.edit')); const canDeleteGroups = computed(() => authStore.hasPermission('public_monitoring.groups.delete'));
const selectedId = computed(() => store.selectedMonitor?.monitor.id || ''); const activeGroups = computed(() => store.groups.filter(group => group.enabled)); const isHTTPType = computed(() => ['http', 'http_keyword', 'http_json'].includes(form.monitorType));
